mapper.select:
select , p.proj_name
from cbs.t_project_enter e left join cbs.t_project p on p.project_id = e.project_id
where e.enter_id = #{id}

mapper.update:
update cbs.t_project_enter
project_id = #{p.project_id}, enter_date = #{p.enter_date}, person_count = #{p.person_count}, leader = #{p.leader}, leader_phone = #{p.leader_phone}, remark = #{p.remark},
where enter_id = #{p.enter_id}
